import { ref, onMounted } from 'vue';
import * as echarts from 'echarts';
import axios from 'axios';
import { API_CONFIG } from './config';
export default {
  __name: 'UserDashboard',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const genderChart = ref(null);

    // 获取并渲染性别分布数据
    const renderGenderChart = async () => {
      try {
        const response = await axios.get(`${API_CONFIG.BASE_URL}/bigdata/gender-distribution`);
        const data = response.data;
        const chart = echarts.init(genderChart.value);
        const option = {
          tooltip: {
            trigger: 'item',
            formatter: '{a} <br/>{b}: {c} ({d}%)'
          },
          legend: {
            orient: 'vertical',
            left: 10,
            data: ['男', '女', '其他']
          },
          series: [{
            name: '性别分布',
            type: 'pie',
            radius: ['50%', '70%'],
            avoidLabelOverlap: false,
            label: {
              show: false,
              position: 'center'
            },
            emphasis: {
              label: {
                show: true,
                fontSize: '18',
                fontWeight: 'bold'
              }
            },
            labelLine: {
              show: false
            },
            data: [{
              value: data.male_count,
              name: '男'
            }, {
              value: data.female_count,
              name: '女'
            }, {
              value: data.other_count,
              name: '其他'
            }]
          }]
        };
        chart.setOption(option);

        // 响应式调整大小
        window.addEventListener('resize', function () {
          chart.resize();
        });
      } catch (error) {
        console.error('获取性别分布数据失败:', error);
      }
    };
    onMounted(() => {
      renderGenderChart();
    });
    const __returned__ = {
      genderChart,
      renderGenderChart,
      ref,
      onMounted,
      get echarts() {
        return echarts;
      },
      get axios() {
        return axios;
      },
      get API_CONFIG() {
        return API_CONFIG;
      }
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
